INSERT INTO core.table_policy (id, org_id, schema_name, table_name, org_deletion, retain_reason, org_export, note, created_at, updated_at) VALUES
	('a355c89c-7a17-4498-a177-a479191a1aba', NULL, 'core', 'organizations', 'retain', 'The organisation row is the anchor of invoices, the contract record and the deletion certificate; it is closed, not removed.', true, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('3c8f03a2-81b6-41f2-b979-028769da8541', NULL, 'core', 'subscriptions', 'retain', 'Contract and subscription history: needed to prove the grace period and for invoicing disputes (retention schedule 2.3).', true, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('53c015a2-1975-4bb7-9b65-de55398e6aa6', NULL, 'core', 'support_sessions', 'retain', 'Access log of AutoEd staff: kept with the audit log for its retention period.', true, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('35cf8585-1934-45f5-a649-d2c595c98383', NULL, 'core', 'compliance_requests', 'retain', 'Request register and deletion certificate source; holds counts and opaque ids only.', true, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('0710ae42-0f1e-46c6-962b-fd80663c57f9', NULL, 'core', 'legal_holds', 'retain', 'Holds are records of legal process and are released, not deleted.', true, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('3a2b0230-13a5-4425-8fcf-88af475b1b9f', NULL, 'core', 'org_export_jobs', 'retain', 'Proof that the exit export was made and what it contained (manifest and sha256).', false, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('a3c1b566-4fa2-412a-811c-4847e50defd3', NULL, 'billing', 'accounts', 'retain', 'AutoEd invoicing record, retained about 8 years (GST and Companies Act; retention schedule 2.3, CONFIRM).', true, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('ec050a06-ce8e-47e4-b346-9b128872f889', NULL, 'billing', 'razorpay_subscriptions', 'retain', 'Payment-provider subscription record for invoices and disputes, about 8 years.', true, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('cb89ab47-b674-4746-84b9-bc25dd4f3e83', NULL, 'billing', 'invoices', 'retain', 'GST tax invoices: statutory retention about 8 years.', true, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('4ccaa172-a0a3-4759-9c04-c6b29fb00896', NULL, 'billing', 'invoice_lines', 'retain', 'GST tax invoice lines: statutory retention about 8 years.', true, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('40953262-5752-4f6d-a249-df045cd84c8a', NULL, 'billing', 'payments', 'retain', 'Payment records: statutory retention about 8 years.', true, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
	('daf8651c-4803-4354-b055-c8739231a316', NULL, 'billing', 'usage', 'retain', 'Metered usage backing invoices: kept with billing records.', true, NULL, '2026-11-24 12:40:09.324467+00', '2026-11-24 12:40:09.324467+00'),
